import { contextMenuStyleKeys, getContextMenuCheckState, getContextMenuPosition, getContextMenuState, getDropdownMenuPosition } from '../lib/core';
import styles from './context-menu.module.scss';
import {
	createMenuFamily,
	type ContextTriggerProps,
	type MenuCheckboxItemProps,
	type MenuContentProps,
	type MenuGroupProps,
	type MenuItemProps,
	type MenuLabelProps,
	type MenuPortalProps,
	type MenuRadioGroupProps,
	type MenuRadioItemProps,
	type MenuRootProps,
	type MenuSeparatorProps,
	type MenuShortcutProps,
	type MenuSubProps,
	type MenuSubTriggerProps,
} from '../dropdown-menu/menu-internals';

const family = createMenuFamily({
	prefix: 'ContextMenu',
	kind: 'context',
	styles,
	keys: contextMenuStyleKeys,
	state: getContextMenuState,
	checkState: getContextMenuCheckState,
	position: ({ triggerRect, contentSize, viewport }) => getContextMenuPosition({ x: triggerRect.left, y: triggerRect.top, contentSize, viewport }),
	subPosition: getDropdownMenuPosition,
});

export interface ContextMenuProps extends MenuRootProps {}
export interface ContextMenuPortalProps extends MenuPortalProps {}
export interface ContextMenuTriggerProps extends ContextTriggerProps {}
export interface ContextMenuContentProps extends Omit<MenuContentProps, 'align' | 'alignOffset' | 'side' | 'sideOffset'> {}
export interface ContextMenuGroupProps extends MenuGroupProps {}
export interface ContextMenuLabelProps extends MenuLabelProps {}
export interface ContextMenuSeparatorProps extends MenuSeparatorProps {}
export interface ContextMenuShortcutProps extends MenuShortcutProps {}
export interface ContextMenuItemProps extends MenuItemProps {}
export interface ContextMenuCheckboxItemProps extends MenuCheckboxItemProps {}
export interface ContextMenuRadioGroupProps extends MenuRadioGroupProps {}
export interface ContextMenuRadioItemProps extends MenuRadioItemProps {}
export interface ContextMenuSubProps extends MenuSubProps {}
export interface ContextMenuSubTriggerProps extends MenuSubTriggerProps {}
export interface ContextMenuSubContentProps extends Omit<MenuContentProps, 'align' | 'alignOffset' | 'side' | 'sideOffset'> {}

export function ContextMenu(props: ContextMenuProps) {
	return family.Root(props);
}
export function ContextMenuPortal(props: ContextMenuPortalProps) {
	return family.MenuPortal(props);
}
export function ContextMenuTrigger(props: ContextMenuTriggerProps) {
	return family.ContextTrigger(props);
}
export function ContextMenuContent(props: ContextMenuContentProps) {
	return family.Content(props);
}
export function ContextMenuGroup(props: ContextMenuGroupProps) {
	return family.Group(props);
}
export function ContextMenuLabel(props: ContextMenuLabelProps) {
	return family.Label(props);
}
export function ContextMenuSeparator(props: ContextMenuSeparatorProps) {
	return family.Separator(props);
}
export function ContextMenuShortcut(props: ContextMenuShortcutProps) {
	return family.Shortcut(props);
}
export function ContextMenuItem(props: ContextMenuItemProps) {
	return family.Item(props);
}
export function ContextMenuCheckboxItem(props: ContextMenuCheckboxItemProps) {
	return family.CheckboxItem(props);
}
export function ContextMenuRadioGroup(props: ContextMenuRadioGroupProps) {
	return family.RadioGroup(props);
}
export function ContextMenuRadioItem(props: ContextMenuRadioItemProps) {
	return family.RadioItem(props);
}
export function ContextMenuSub(props: ContextMenuSubProps) {
	return family.Sub(props);
}
export function ContextMenuSubTrigger(props: ContextMenuSubTriggerProps) {
	return family.SubTrigger(props);
}
export function ContextMenuSubContent(props: ContextMenuSubContentProps) {
	return family.SubContent(props);
}

export default ContextMenu;

@use '../../../styles/variables/colors' as *;

// 根容器
.root {
	display: inline-flex;
}

// 触发器（默认无样式，接收右键事件）
.trigger {
	display: inline-flex;
}

// 弹出内容面板
.content {
	position: fixed;
	z-index: $z-dropdown;
	min-width: 8rem;
	max-width: calc(100vw - 1rem);
	max-height: calc(100vh - 1rem);
	overflow-x: hidden;
	overflow-y: auto;
	border-radius: $radius-md;
	border: 1px solid $border;
	background-color: $popover;
	color: $popover-foreground;
	padding: $spacing-1;
	box-shadow: $shadow-md;
	outline: none;
	transition:
		opacity $transition-fast,
		visibility $transition-fast,
		transform $transition-fast;

	&[data-state='closed'] {
		opacity: 0;
		visibility: hidden;
		pointer-events: none;
		transform: scale(0.95);
	}

	&[data-state='open'] {
		opacity: 1;
		visibility: visible;
		pointer-events: auto;
		transform: scale(1);
	}
}

// 子菜单弹出面板
.subContent {
	position: fixed;
	z-index: $z-dropdown;
	min-width: 8rem;
	overflow: hidden;
	border-radius: $radius-md;
	border: 1px solid $border;
	background-color: $popover;
	color: $popover-foreground;
	padding: $spacing-1;
	box-shadow: $shadow-lg;
	outline: none;
	transition:
		opacity $transition-fast,
		visibility $transition-fast,
		transform $transition-fast;

	&[data-state='closed'] {
		opacity: 0;
		visibility: hidden;
		pointer-events: none;
		transform: translateX(-0.25rem);
	}

	&[data-state='open'] {
		opacity: 1;
		visibility: visible;
		pointer-events: auto;
		transform: translate(0, 0);
	}
}

// 分组容器（占位，无视觉样式）
.group {
	display: block;
}

// 菜单项
.item {
	position: relative;
	display: flex;
	align-items: center;
	gap: $spacing-2;
	border-radius: $radius-sm;
	padding: $spacing-1_5 $spacing-2;
	font-size: $text-sm;
	line-height: $leading-normal;
	color: $popover-foreground;
	outline: none;
	cursor: default;
	user-select: none;

	&[data-highlighted='true'] {
		background-color: $accent;
		color: $accent-foreground;
	}

	&[data-inset='true'] {
		padding-left: $spacing-8;
	}

	&[data-variant='destructive'] {
		color: $destructive;

		&[data-highlighted='true'] {
			background-color: color-mix(in srgb, $destructive 10%, transparent);
			color: $destructive;
		}
	}

	&[data-disabled='true'] {
		pointer-events: none;
		opacity: 0.5;
	}

	& > svg {
		pointer-events: none;
		flex-shrink: 0;
		width: 1rem;
		height: 1rem;
		color: $muted-foreground;
	}

	&[data-variant='destructive'] > svg {
		color: $destructive;
	}
}

// 复选框菜单项
.checkboxItem {
	position: relative;
	display: flex;
	align-items: center;
	gap: $spacing-2;
	border-radius: $radius-sm;
	padding: $spacing-1_5 $spacing-2 $spacing-1_5 $spacing-8;
	font-size: $text-sm;
	line-height: $leading-normal;
	color: $popover-foreground;
	outline: none;
	cursor: default;
	user-select: none;

	&[data-highlighted='true'] {
		background-color: $accent;
		color: $accent-foreground;
	}

	&[data-disabled='true'] {
		pointer-events: none;
		opacity: 0.5;
	}

	& > svg {
		pointer-events: none;
		flex-shrink: 0;
		width: 1rem;
		height: 1rem;
		color: $muted-foreground;
	}
}

// 单选组容器
.radioGroup {
	display: block;
}

// 单选菜单项
.radioItem {
	position: relative;
	display: flex;
	align-items: center;
	gap: $spacing-2;
	border-radius: $radius-sm;
	padding: $spacing-1_5 $spacing-2 $spacing-1_5 $spacing-8;
	font-size: $text-sm;
	line-height: $leading-normal;
	color: $popover-foreground;
	outline: none;
	cursor: default;
	user-select: none;

	&[data-highlighted='true'] {
		background-color: $accent;
		color: $accent-foreground;
	}

	&[data-disabled='true'] {
		pointer-events: none;
		opacity: 0.5;
	}

	& > svg {
		pointer-events: none;
		flex-shrink: 0;
		width: 1rem;
		height: 1rem;
		color: $muted-foreground;
	}
}

// 勾选/单选指示器（绝对定位在左侧）
.indicator {
	position: absolute;
	left: $spacing-2;
	display: inline-flex;
	width: 0.875rem;
	height: 0.875rem;
	align-items: center;
	justify-content: center;
	color: currentcolor;

	.checkIcon {
		width: 1rem;
		height: 1rem;
	}

	.radioIcon {
		width: 0.5rem;
		height: 0.5rem;
		fill: currentColor;
	}
}

// 标签
.label {
	padding: $spacing-1_5 $spacing-2;
	font-size: $text-sm;
	font-weight: $font-medium;
	color: $foreground;

	&[data-inset='true'] {
		padding-left: $spacing-8;
	}
}

// 分隔线
.separator {
	margin: $spacing-1 (-$spacing-1);
	height: 1px;
	background-color: $border;
}

// 快捷键文本
.shortcut {
	margin-left: auto;
	font-size: $text-xs;
	letter-spacing: 0.1em;
	color: $muted-foreground;
}

// 子菜单触发器
.subTrigger {
	position: relative;
	display: flex;
	align-items: center;
	gap: $spacing-2;
	border-radius: $radius-sm;
	padding: $spacing-1_5 $spacing-2;
	font-size: $text-sm;
	line-height: $leading-normal;
	color: $popover-foreground;
	outline: none;
	cursor: default;
	user-select: none;

	&[data-highlighted='true'],
	&[data-state='open'] {
		background-color: $accent;
		color: $accent-foreground;
	}

	&[data-inset='true'] {
		padding-left: $spacing-8;
	}

	&[data-disabled='true'] {
		pointer-events: none;
		opacity: 0.5;
	}

	& > svg {
		pointer-events: none;
		flex-shrink: 0;
		width: 1rem;
		height: 1rem;
		color: $muted-foreground;
	}
}

// 子菜单箭头
.chevron {
	margin-left: auto;
	width: 1rem;
	height: 1rem;

	[dir='rtl'] & {
		transform: rotate(180deg);
	}
}

// Context menus share the generic dropdown surface and row styling interfaces.
.content,
.subContent {
	min-width: var(--tile-menu-min-width, 8rem);
	border-radius: var(--tile-menu-panel-radius, $radius-md);
	border-color: var(--tile-menu-border, $border);
	background-color: var(--tile-menu-background, $popover);
	color: var(--tile-menu-foreground, $popover-foreground);
	padding: var(--tile-menu-padding, $spacing-1);
}
.content {
	box-shadow: var(--tile-menu-shadow, $shadow-md);
}
.subContent {
	box-shadow: var(--tile-menu-shadow, $shadow-lg);
}
.item,
.checkboxItem,
.radioItem,
.subTrigger {
	border-radius: var(--tile-menu-item-radius, $radius-sm);
	font-size: var(--tile-menu-font-size, $text-sm);
	line-height: var(--tile-menu-line-height, $leading-normal);
	color: var(--tile-menu-foreground, $popover-foreground);
	&[data-highlighted='true'] {
		background-color: var(--tile-menu-highlight-background, $accent);
		color: var(--tile-menu-highlight-foreground, $accent-foreground);
	}
	& > svg {
		color: var(--tile-menu-subtle, $muted-foreground);
	}
	&:focus-visible {
		box-shadow: var(--tile-menu-focus-shadow, none);
	}
}
.item,
.subTrigger {
	padding: var(--tile-menu-item-padding, $spacing-1_5 $spacing-2);
}
.checkboxItem,
.radioItem {
	padding: var(--tile-menu-check-padding, $spacing-1_5 $spacing-2 $spacing-1_5 $spacing-8);
}
.subTrigger[data-state='open'] {
	background-color: var(--tile-menu-highlight-background, $accent);
	color: var(--tile-menu-highlight-foreground, $accent-foreground);
}
.item[data-variant='destructive'] {
	color: var(--tile-menu-destructive-foreground, $destructive);
	& > svg {
		color: var(--tile-menu-destructive-foreground, $destructive);
	}
	&[data-highlighted='true'] {
		background-color: var(--tile-menu-destructive-background, color-mix(in srgb, $destructive 10%, transparent));
		color: var(--tile-menu-destructive-foreground, $destructive);
	}
}
.label {
	padding: var(--tile-menu-label-padding, $spacing-1_5 $spacing-2);
	font-size: var(--tile-menu-label-font-size, $text-sm);
	font-weight: var(--tile-menu-label-font-weight, $font-medium);
	color: var(--tile-menu-label-foreground, $foreground);
}
.item[data-inset='true'],
.subTrigger[data-inset='true'],
.label[data-inset='true'] {
	padding-left: $spacing-8;
}
.separator {
	background-color: var(--tile-menu-separator, $border);
}
.shortcut {
	color: var(--tile-menu-subtle, $muted-foreground);
}

@media (prefers-reduced-motion: reduce) {
	.content,
	.subContent {
		transition: none;
	}
}
